class FileUploader{constructor(zoneElement,options={}){this.zone=zoneElement;this.input=this.zone.querySelector('input[type="file"]');this.preview=this.zone.querySelector('.upload-preview');this.progress=this.zone.querySelector('.upload-progress');this.label=this.zone.querySelector('.upload-label');this.options={maxSize: options.maxSize||5*1024*1024,allowedTypes: options.allowedTypes||null,multiple: options.multiple||false,showPreview: options.showPreview!==false,simulateUpload: options.simulateUpload!==false,onFileSelect: options.onFileSelect||null,onUploadComplete: options.onUploadComplete||null,onError: options.onError||null,...options};this.selectedFiles=[];this.isUploading=false;this.init();}init(){if(!this.input){console.error('FileUploader: No input element found');return;}this.setupDragAndDrop();this.setupClickUpload();this.setupRemoveButton();}setupDragAndDrop(){['dragenter','dragover','dragleave','drop'].forEach(eventName=>{this.zone.addEventListener(eventName,this.preventDefaults,false);document.body.addEventListener(eventName,this.preventDefaults,false);});['dragenter','dragover'].forEach(eventName=>{this.zone.addEventListener(eventName,()=>{this.zone.classList.add('drag-over');},false);});['dragleave','drop'].forEach(eventName=>{this.zone.addEventListener(eventName,()=>{this.zone.classList.remove('drag-over');},false);});this.zone.addEventListener('drop',(e)=>{const dt=e.dataTransfer;const files=dt.files;this.handleFiles(files);},false);}setupClickUpload(){this.input.addEventListener('change',(e)=>{if(e.target.files.length>0){this.handleFiles(e.target.files);}});}setupRemoveButton(){const removeBtn=this.zone.querySelector('.btn-remove-upload');if(removeBtn){removeBtn.addEventListener('click',(e)=>{e.stopPropagation();this.removeFile();});}}preventDefaults(e){e.preventDefault();e.stopPropagation();}handleFiles(files){if(this.isUploading){this.showError('Aguarde o upload atual terminar');return;}const filesArray=Array.from(files);const validFiles=filesArray.filter(file=>this.validateFile(file));if(validFiles.length===0){return;}if(this.options.multiple){this.selectedFiles=validFiles;this.showMultiplePreview(validFiles);}else{this.selectedFiles=[validFiles[0]];this.handleSingleFile(validFiles[0]);}if(this.options.onFileSelect){this.options.onFileSelect(this.selectedFiles);}}handleSingleFile(file){if(file.type.startsWith('image/')){this.showImagePreview(file);}else{this.showFileInfo(file);}if(this.options.simulateUpload){this.simulateUpload();}}validateFile(file){this.clearError();this.zone.classList.remove('upload-error');const accept=this.input.getAttribute('accept');if(accept&&!this.validateType(file,accept)){this.showError(`Tipo de arquivo não aceito. Aceitos: ${accept}`);this.zone.classList.add('upload-error');return false;}if(file.size>this.options.maxSize){const maxSizeMB=(this.options.maxSize/(1024*1024)).toFixed(1);this.showError(`Arquivo muito grande. Máximo: ${maxSizeMB}MB`);this.zone.classList.add('upload-error');return false;}return true;}validateType(file,accept){const acceptTypes=accept.split(',').map(type=>type.trim());for(const acceptType of acceptTypes){if(acceptType.startsWith('.')){const extension=acceptType.toLowerCase();if(file.name.toLowerCase().endsWith(extension)){return true;}}else if(acceptType.includes('*')){const[type]=acceptType.split('/');if(file.type.startsWith(type+'/')){return true;}}else if(file.type===acceptType){return true;}}return false;}showImagePreview(file){if(!this.preview)return;const reader=new FileReader();reader.onload=(e)=>{let img=this.preview.querySelector('img');if(!img){img=document.createElement('img');this.preview.innerHTML='';this.preview.appendChild(img);if(!this.preview.querySelector('.btn-remove-upload')){const removeBtn=document.createElement('button');removeBtn.type='button';removeBtn.className='btn-remove-upload';removeBtn.innerHTML='<i class="bi bi-x-circle"></i>';removeBtn.addEventListener('click',(e)=>{e.stopPropagation();this.removeFile();});this.preview.appendChild(removeBtn);}}img.src=e.target.result;img.alt=file.name;if(this.label)this.label.style.display='none';this.preview.style.display='block';this.zone.classList.add('upload-success');};reader.readAsDataURL(file);}showFileInfo(file){if(!this.preview)return;const iconClass=this.getFileIcon(file);this.preview.innerHTML=`<div class="file-info"><i class="bi ${iconClass}"></i><div class="file-details"><div class="file-name">${file.name}</div><div class="file-size">${this.formatFileSize(file.size)}</div></div></div>`;const removeBtn=document.createElement('button');removeBtn.type='button';removeBtn.className='btn-remove-upload';removeBtn.innerHTML='<i class="bi bi-x-circle"></i>';removeBtn.addEventListener('click',(e)=>{e.stopPropagation();this.removeFile();});this.preview.appendChild(removeBtn);if(this.label)this.label.style.display='none';this.preview.style.display='block';this.zone.classList.add('upload-success');}showMultiplePreview(files){let grid=this.zone.querySelector('.uploaded-files-grid');if(!grid){grid=document.createElement('div');grid.className='uploaded-files-grid';this.zone.appendChild(grid);}grid.innerHTML='';files.forEach((file,index)=>{const item=document.createElement('div');item.className='uploaded-file-item';if(file.type.startsWith('image/')){const reader=new FileReader();reader.onload=(e)=>{item.innerHTML=`<img src="${e.target.result}" alt="${file.name}"><button type="button" class="file-remove" data-index="${index}"><i class="bi bi-x"></i></button>`;item.querySelector('.file-remove').addEventListener('click',()=>{this.removeFileByIndex(index);});};reader.readAsDataURL(file);}else{const iconClass=this.getFileIcon(file);item.innerHTML=`<div class="file-info" style="height: 120px;padding: 1rem;flex-direction: column;justify-content: center;"><i class="bi ${iconClass}" style="font-size: 2rem;"></i><div class="file-name" style="font-size: 0.7rem;margin-top: 0.5rem;">${file.name}</div></div><button type="button" class="file-remove" data-index="${index}"><i class="bi bi-x"></i></button>`;item.querySelector('.file-remove').addEventListener('click',()=>{this.removeFileByIndex(index);});}grid.appendChild(item);});if(this.label)this.label.style.display='none';}simulateUpload(){if(!this.progress)return;this.isUploading=true;this.zone.classList.add('uploading');this.progress.style.display='block';const fill=this.progress.querySelector('.progress-fill');const text=this.progress.querySelector('.progress-text');let percent=0;const interval=setInterval(()=>{percent+=10;if(fill)fill.style.width=`${percent}%`;if(text)text.textContent=`${percent}%`;if(percent>=100){clearInterval(interval);this.isUploading=false;this.zone.classList.remove('uploading');setTimeout(()=>{if(this.progress)this.progress.style.display='none';if(this.options.onUploadComplete){this.options.onUploadComplete(this.selectedFiles);}},500);}},100);}removeFile(){this.selectedFiles=[];this.input.value='';if(this.preview){this.preview.style.display='none';this.preview.innerHTML='';}if(this.label){this.label.style.display='block';}if(this.progress){this.progress.style.display='none';}this.zone.classList.remove('upload-success','upload-error');this.clearError();}removeFileByIndex(index){this.selectedFiles.splice(index,1);if(this.selectedFiles.length===0){this.removeFile();}else{this.showMultiplePreview(this.selectedFiles);}}showError(message){this.clearError();const errorDiv=document.createElement('div');errorDiv.className='upload-error-message';errorDiv.innerHTML=`<i class="bi bi-exclamation-triangle-fill"></i><span>${message}</span>`;this.zone.appendChild(errorDiv);if(this.options.onError){this.options.onError(message);}}clearError(){const existingError=this.zone.querySelector('.upload-error-message');if(existingError){existingError.remove();}}getFileIcon(file){const type=file.type;const name=file.name.toLowerCase();if(type.startsWith('image/'))return 'bi-file-earmark-image-fill';if(type.includes('pdf')||name.endsWith('.pdf'))return 'bi-file-earmark-pdf-fill';if(type.includes('word')||name.endsWith('.doc')||name.endsWith('.docx'))return 'bi-file-earmark-word-fill';if(type.includes('excel')||name.endsWith('.xls')||name.endsWith('.xlsx'))return 'bi-file-earmark-excel-fill';if(type.includes('powerpoint')||name.endsWith('.ppt')||name.endsWith('.pptx'))return 'bi-file-earmark-ppt-fill';if(name.endsWith('.zip')||name.endsWith('.rar')||name.endsWith('.7z'))return 'bi-file-earmark-zip-fill';if(type.includes('text')||name.endsWith('.txt'))return 'bi-file-earmark-text-fill';if(name.endsWith('.js')||name.endsWith('.css')||name.endsWith('.html'))return 'bi-file-earmark-code-fill';return 'bi-file-earmark-fill';}formatFileSize(bytes){if(bytes===0)return '0 B';if(bytes<1024)return bytes+' B';if(bytes<1024*1024)return(bytes/1024).toFixed(1)+' KB';return(bytes/(1024*1024)).toFixed(1)+' MB';}}document.addEventListener('DOMContentLoaded',function(){const uploadZones=document.querySelectorAll('.upload-zone');uploadZones.forEach(zone=>{if(zone.dataset.uploaderInitialized)return;const options={maxSize: parseInt(zone.dataset.maxSize)||16*1024*1024,multiple: zone.querySelector('input[type="file"]')?.hasAttribute('multiple')||false,showPreview: zone.dataset.showPreview!=='false',simulateUpload: zone.dataset.simulateUpload!=='false'};new FileUploader(zone,options);zone.dataset.uploaderInitialized='true';});console.log('%c✨ FileUploader System Initialized','color: #10b981;font-weight: bold;font-size: 14px;');console.log(`Found ${uploadZones.length}upload zone(s)`);});if(typeof module!=='undefined'&&module.exports){module.exports=FileUploader;}